{
  "name": "A2D多功能检测板",
  "name_en": "A2D Sense Board",
  "manufacturer": "A2D",
  "description": "这是一种用于实验室电学测试的多功能检测电路板，可测量电压、电流和温度，并支持校准。它适合嵌入测试夹具、原型系统或自动化实验平台中，用于基础信号采集与状态监测。",
  "description_en": "This is a multifunction measurement board for laboratory electrical testing. It can measure voltage, current, and temperature, and supports calibration. It is suitable for integration into test fixtures, prototype systems, or automated lab setups for basic signal acquisition and condition monitoring.",
  "actions": [
    {
      "action_name": "auto-calibrate_current",
      "description": "校准电流测量。",
      "description_en": "Calibrate current measurement."
    },
    {
      "action_name": "auto-calibrate_voltage",
      "description": "校准电压测量。",
      "description_en": "Calibrate voltage measurement."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化检测板并准备测量。",
      "description_en": "Initialize the sense board and prepare it for measurement."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量电流。",
      "description_en": "Measure current."
    },
    {
      "action_name": "auto-measure_temperature",
      "description": "测量温度。",
      "description_en": "Measure temperature."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量电压。",
      "description_en": "Measure voltage."
    },
    {
      "action_name": "auto-reset_calibration",
      "description": "重置校准参数。",
      "description_en": "Reset calibration parameters."
    },
    {
      "action_name": "auto-set_i2c_adc_addr",
      "description": "设置I2C模数转换器地址。",
      "description_en": "Set the I2C ADC address."
    },
    {
      "action_name": "auto-set_led",
      "description": "设置指示灯状态。",
      "description_en": "Set the LED state."
    }
  ],
  "tag_hints": [
    "voltage measurement",
    "current measurement",
    "temperature measurement",
    "sense board",
    "I2C ADC",
    "measurement calibration",
    "test fixture instrumentation"
  ]
}

